        spin_unlock(&device_spinlock);
        mutex_unlock(&device_mutex);

        // Handle blocking or non-blocking I/O
        if (file->f_flags & O_NONBLOCK)
            return -EAGAIN;

        // Wait for data to be available
        wait_event_interruptible(data_available_queue, !sound_timer_queue_empty());
    }

    // Read data from the queue into the user buffer
